SELECT session_id, MONTH(event_time) AS event_month, COUNT(DISTINCT duration_sec) AS unique_pages, ROUND(STDDEV(duration_sec), 2) AS stddev_duration_sec, SUM(CASE WHEN event_type = 'click' THEN 1 ELSE 0 END) AS click_count FROM web_events WHERE session_id IN (8, 11, 38) AND TO_DATE(event_time) < '2025-02-01' GROUP BY session_id, MONTH(event_time) HAVING ROUND(STDDEV(duration_sec), 2) > 44 ORDER BY session_id DESC, click_count DESC;
